/**
 * Example plugin.js for rule-mcp.
 * Provides custom guardrails and generators.
 *
 * @module my-custom-rules/plugin
 */

/** @type {Array<{ id: string, label: string, description: string, check: Function }>} */
export const guardrails = [
  {
    id: "custom-two-spaces",
    label: "2-space indentation",
    description: "Code must use 2-space indentation (not 4).",
    check: (code) => {
      const twoSpaceIndent = code.match(/^(\s{2})[^\s]/gm);
      return {
        pass: !twoSpaceIndent || twoSpaceIndent.length === 0,
        failCount: twoSpaceIndent?.length || 0,
        detail: twoSpaceIndent ? twoSpaceIndent.slice(0, 5) : [],
        suggestion: "Use 2-space indentation instead of 4.",
      };
    },
  },
  {
    id: "custom-line-length",
    label: "Max line length 100",
    description: "Maximum line length should be 100 characters.",
    check: (code) => {
      const longLines = code.split("\n").filter(l => l.length > 100);
      return {
        pass: longLines.length === 0,
        failCount: longLines.length,
        detail: longLines.slice(0, 5).map(l => l.slice(0, 80) + "..."),
        suggestion: "Break lines longer than 100 characters.",
      };
    },
  },
];

/** @type {Object<string, Function>} */
export const generators = {
  configFile: () => "// Custom config generated by my-custom-rules plugin\n",
};
